-- membership  (/membership)
--   from https://lcci.com.pk/membership.php (1316 chars)
UPDATE content_pages p
  JOIN content_items ci ON ci.id = p.content_item_id
   SET p.body_en = '<p>

							Membership Department

							</p><p>Membership Department is one of the most important departments of LCCI. It is responsible for processing

	of  new membership applications, renewals of membership, issuance of LCCI member cards, attestation of certificate of origin, attestation of commercial documents, issuance of visa recommendation letters, issuance of visa invitation letters and co-ordination in conducting annual election of LCCI.</p>

<p></p>	

						Membership Eligibility

						<ol>

						  <li>The application for grant of membership shell be proposed and seconded by existing members of the Lahore Chamber of Commerce and Industry.</li>

						  <li>The prospective member has a valid national tax number and sales tax registration, if applicable.	</li>

						  <li>The membership shall be renewable on annual basis subject to fulfillment of following conditions. </li>

						  <li>The prospective member has no criminal conviction.</li>

						  <li>Proof of filing  income tax return and sales tax, if applicable, for latest  preceding assessment year. </li>

						</ol>

<p></p>

						Classes of Membership

						<p>There shall be two classes of memberships in Lahore Chamber of Commerce and Industry.</p>

						Membership Procedure

						<ul>

						  <li>Written application on firm’s letterhead addressed to secretary general LCCI for grant of member </li>

						  <li>Completely filled in Signature / Identity Card<br />

						  </li>

						  <li>Photocopy of C.N.I.C of the proprietor</li>

						  <li>Photocopy of Sales-Tax Registration number certificate (if applicable) </li>

						</ul>

<p></p>

						 
						

						

  <p></p>'
 WHERE ci.content_type = 'page'
   AND ci.slug = 'membership'
   AND p.body_en IS NULL;

UPDATE content_items
   SET status = 'published', published_at = '2026-10-01 05:00:00.000'
 WHERE content_type = 'page' AND slug = 'membership'
   AND status = 'draft'
   AND EXISTS (
     SELECT 1 FROM content_pages p
      WHERE p.content_item_id = content_items.id AND p.body_en IS NOT NULL
   );

-- membership-why-join  (/membership/why-join)
--   from https://lcci.com.pk/members.php?id=83 (2130 chars)
UPDATE content_pages p
  JOIN content_items ci ON ci.id = p.content_item_id
   SET p.body_en = '<h2>Membership Benefits</h2><p>LCCI one window smart services are the bench mark of excellence, where the member can avail exclusive services in the following areas:</p>

<ul>
	<li>National Database &amp; Registration Authority.  (NADRA)</li>
	<li>Lahore Traffic Police (Driving License)</li>
	<li>Passport</li>
	<li>Federal of Board of Revenue (FBR)</li>
	<li>Lahore Electric Supply Company (LESCO)</li>
	<li>Excise and Taxation</li>
	<li>Small and Medium Enterprises Development. (SEMEDA)</li>
	<li>Punjab Employee Social Security Institution.  (PESSI)</li>
	<li>State Bank of Pakistan</li>
	<li>Bank of Punjab</li>
	<li>United Bank Limited</li>
	<li>Web Based One Customs. (WeBoc)</li>
	<li>Water and Sanitation Agency. (WASA)</li>
	<li>Pakistan International Airlines. (PIA)</li>
	<li>Punjab Revenue Authority</li>
	<li>Lahore Development Authority. (LDA)</li>
	<li>Labour Department</li>
</ul>

<p>Provides an opportunity to its members to involve in Chamber''s activities and meet Government officials, Federal and Provincial Ministers, Ambassadors and Leading Businessmen both Local and International.</p>

<p>LCCI always remains in consultation with Government Departments on various issues related to business community, which provide opportunities for members to share their views and concerns.</p>

<p>Membership is compulsory to get Certificates of Origin, WeBOC registrations and also endorsement of all necessary commercial documents.</p>

<p>The Research and Development Department provides an intensive business information and consultancy on various business issues to its members.</p>

<p>The department also explains new regulations, procedures and provides in-depth trade &amp; investment advice.</p>

<p>Standing Committees actively monitor and pursue issues concerning trade and industry, foreign investment regulations, tourism, taxation, infrastructure requirements etc.</p>

<p>LCCI arrange regularly foreign Business delegations which provide opportunities to the delegates to meet their counterparts in the respective countries.</p>

<p>Members get priority access to the library which has a huge collection of reference books and latest trade directories.</p>

<p>Notices regarding business opportunities are regularly circulated in Lahore Chamber News.</p>

<p>Chamber members are nominated for various Government advisory committees and statutory boards where national policies are formulated.</p>

<p>**********</p>'
 WHERE ci.content_type = 'page'
   AND ci.slug = 'membership-why-join'
   AND p.body_en IS NULL;

UPDATE content_items
   SET status = 'published', published_at = '2026-10-01 05:00:00.000'
 WHERE content_type = 'page' AND slug = 'membership-why-join'
   AND status = 'draft'
   AND EXISTS (
     SELECT 1 FROM content_pages p
      WHERE p.content_item_id = content_items.id AND p.body_en IS NOT NULL
   );

